# ---- velotour.kz (туроператор Velotour Kazakhstan): факты со страниц маршрутов, тексты — собственные ----
VT = lambda name, slug: ('Источник: velotour.kz — ' + name, 'https://velotour.kz/routes/' + slug + '/')
VTT = 'Маршрут проходит туроператор Velotour Kazakhstan (velotour.kz) с машиной сопровождения; даты и условия — на странице источника.'

